 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = max(counts, key=counts.get)
    seen = set()
    objects = Counter()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            objects[color] += 1
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
    cells = []
    for color in sorted(objects, reverse=True):
        cells.extend([color] * objects[color])
    cells = (cells + [background] * 6)[:6]
    return [cells[:3], cells[3:]]
